        SkRole.SNACK_FRAME -> of(SkRole.ACCENT)
        SkRole.HINT_GROUND -> of(SkRole.BACKGROUND)
        SkRole.HINT_TEXT -> of(SkRole.TEXT)
        SkRole.HINT_ERROR -> 0xFFFF0000.toInt()
    }
